contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            ownerBefore == ownerAfter && depositsBefore == depositsAfter &&
            (
                (reverted && cBalBefore < _value && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore) ||
                (!reverted && cBalBefore >= _value && cBalAfter == cBalBefore - _value && thisBalAfter == thisBalBefore + _value)
            )
        );
    }

    receive() external payable {}
}

